"use client";

import { useEffect, useMemo, useState } from "react";
import { useTheme } from "next-themes";
import {
  Activity, AlarmClock, AlertTriangle, BarChart3, Bell, BriefcaseBusiness, Building2, CalendarClock, Check, CheckCircle2,
  ChevronLeft, CircleDollarSign, ClipboardCheck, Clock3, Copy, FileClock, FileText, FolderKanban, Gauge, HeartPulse,
  LayoutDashboard, Menu, Moon, PackageCheck, Play, Plus, Printer, RefreshCcw, RotateCcw, Search, Settings2, ShieldCheck,
  Square, Sun, TrendingUp, Upload, Users, WalletCards, X,
} from "lucide-react";
import { createOfficeSeed } from "@/data/accounting-office";
import {
  canArchiveClient, clientHealth, clientProfitability, dashboardMetrics, detectRevenueOpportunities, employeeWorkload,
  feeSummary, fileCompletion, generateMonthlyFiles, officeId, startTimer, stopTimer,
} from "@/lib/accounting-office/engine";
import { loadOfficeData, resetOfficeDemo, saveOfficeData, subscribeOffice } from "@/lib/storage/accounting-office";
import { activeCompanyId } from "@/lib/storage/accounting";
import type {
  AccountingOfficeData, ClientProfitability, Locale, MonthlyFileStatus, OfficeClient, OfficeDeadlineLevel,
  OfficePriority, OfficeTaskStatus, RequiredDocumentStatus, RevenueOpportunity, WorkloadLevel,
} from "@/types";

type View = "overview" | "clients" | "files" | "tasks" | "documents" | "deadlines" | "reviews" | "team" | "time" | "fees" | "profitability" | "opportunities" | "reports" | "settings";
type Icon = typeof LayoutDashboard;
type Flash = (message: string) => void;

const views: { id: View; ar: string; en: string; icon: Icon }[] = [
  { id: "overview", ar: "نظرة عامة", en: "Overview", icon: LayoutDashboard }, { id: "clients", ar: "العملاء", en: "Clients", icon: Building2 },
  { id: "files", ar: "الملفات الشهرية", en: "Monthly files", icon: FolderKanban }, { id: "tasks", ar: "المهام", en: "Tasks", icon: ClipboardCheck },
  { id: "documents", ar: "المستندات الناقصة", en: "Missing documents", icon: FileClock }, { id: "deadlines", ar: "المواعيد والالتزامات", en: "Deadlines", icon: CalendarClock },
  { id: "reviews", ar: "المراجعات", en: "Reviews", icon: ShieldCheck }, { id: "team", ar: "فريق العمل", en: "Team", icon: Users },
  { id: "time", ar: "الوقت والتكلفة", en: "Time & cost", icon: Clock3 }, { id: "fees", ar: "الأتعاب والتحصيل", en: "Fees & collection", icon: WalletCards },
  { id: "profitability", ar: "ربحية العملاء", en: "Client profitability", icon: Gauge }, { id: "opportunities", ar: "فرص زيادة الإيرادات", en: "Revenue opportunities", icon: TrendingUp },
  { id: "reports", ar: "تقارير المكتب", en: "Office reports", icon: BarChart3 }, { id: "settings", ar: "إعدادات المكتب", en: "Office settings", icon: Settings2 },
];

const labels = {
  task: { new: "جديدة", "in-progress": "جاري العمل", "waiting-client": "انتظار العميل", "ready-review": "جاهزة للمراجعة", completed: "مكتملة", "carried-forward": "مرحّلة", cancelled: "ملغاة" },
  file: { "not-started": "لم يبدأ", "waiting-documents": "بانتظار المستندات", recording: "قيد التسجيل", adjusting: "قيد التسوية", "ready-review": "جاهز للمراجعة", "changes-required": "يحتاج تعديلات", reviewed: "تمت المراجعة", "ready-delivery": "جاهز للتسليم", closed: "مغلق", overdue: "متأخر" },
  document: { "not-requested": "لم يُطلب", requested: "تم الطلب", partial: "استلام جزئي", received: "تم الاستلام", "not-required": "غير مطلوب", overdue: "متأخر" },
  fee: { draft: "مسودة", due: "مستحقة", partial: "محصلة جزئيًا", collected: "محصلة", overdue: "متأخرة", cancelled: "ملغاة" },
  opportunity: { new: "فرصة جديدة", contact: "تحتاج تواصل", offered: "تم العرض", negotiating: "قيد التفاوض", won: "تمت الموافقة", lost: "مرفوضة", deferred: "مؤجلة" },
} as const;

const money = (value: number, currency = "EGP", locale = "ar-EG") => new Intl.NumberFormat(locale, { style: "currency", currency, maximumFractionDigits: 0 }).format(value);
const shortDate = (value: string, ar: boolean) => new Intl.DateTimeFormat(ar ? "ar-EG" : "en-GB", { day: "numeric", month: "short", year: "numeric" }).format(new Date(`${value}T12:00:00`));
const clientName = (data: AccountingOfficeData, id?: string) => data.clients.find((item) => item.id === id)?.tradeName || "—";
const employeeName = (data: AccountingOfficeData, id?: string) => data.employees.find((item) => item.id === id)?.name || "—";

export function AccountingOfficeHub({ locale }: { locale: Locale }) {
  const ar = locale === "ar", { resolvedTheme, setTheme } = useTheme();
  const [data, setData] = useState(() => createOfficeSeed("personal"));
  const [view, setView] = useState<View>("overview"), [menuOpen, setMenuOpen] = useState(false), [query, setQuery] = useState(""), [notice, setNotice] = useState("");
  const [period, setPeriod] = useState("2026-08"), [clientFormOpen, setClientFormOpen] = useState(false), [selectedClientId, setSelectedClientId] = useState("client-1");
  useEffect(() => { setData(loadOfficeData()); return subscribeOffice(setData); }, []);
  const commit = (next: AccountingOfficeData) => { setData(next); saveOfficeData(next); };
  const flash: Flash = (message) => { setNotice(message); window.setTimeout(() => setNotice(""), 3200); };
  const changeView = (next: View) => { setView(next); setMenuOpen(false); };
  const active = views.find((item) => item.id === view)!;

  const addClient = (client: OfficeClient) => { commit({ ...data, clients: [client, ...data.clients], activities: [{ id: officeId("activity"), type: "client", description: `تمت إضافة العميل ${client.tradeName}`, clientId: client.id, at: new Date().toISOString() }, ...data.activities] }); setSelectedClientId(client.id); setClientFormOpen(false); flash(ar ? "تم حفظ العميل في مساحة الشركة الحالية" : "Client saved in the active company workspace"); };

  return <div className="min-h-[calc(100vh-68px)] bg-daftar-bg" data-no-bilingual>
    <div className="mx-auto flex max-w-[1680px] gap-0 px-3 py-5 lg:px-5">
      <aside className={`${menuOpen ? "fixed inset-0 z-50 flex bg-slate-950/40 p-3" : "hidden"} lg:sticky lg:top-[88px] lg:flex lg:h-[calc(100vh-108px)] lg:w-[270px] lg:shrink-0 lg:bg-transparent lg:p-0`}>
        <div className="flex h-full w-[285px] flex-col overflow-hidden rounded-3xl bg-[#0d315c] text-white shadow-2xl lg:w-full">
          <div className="flex items-center justify-between border-b border-white/10 p-5"><div><small className="text-white/55">FINORA OFFICE</small><b className="mt-1 block leading-6">{ar ? data.office.nameAr : data.office.nameEn}</b></div><button aria-label="close menu" className="rounded-xl p-2 hover:bg-white/10 lg:hidden" onClick={() => setMenuOpen(false)}><X/></button></div>
          <nav className="grid gap-1 overflow-y-auto p-3">{views.map((item) => { const ItemIcon = item.icon; return <button key={item.id} onClick={() => changeView(item.id)} className={`flex items-center gap-3 rounded-xl px-4 py-2.5 text-start text-sm font-bold transition ${view === item.id ? "bg-white text-[#0d315c] shadow-lg" : "text-white/72 hover:bg-white/10 hover:text-white"}`}><ItemIcon size={18}/><span>{ar ? item.ar : item.en}</span></button>; })}</nav>
          <div className="m-3 mt-auto rounded-2xl bg-white/10 p-4"><div className="flex items-center gap-2 text-emerald-300"><HeartPulse size={17}/><b>{ar ? "صحة محفظة العملاء" : "Client portfolio health"}</b></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-white/15"><i className="block h-full w-[78%] rounded-full bg-emerald-400"/></div><small className="mt-2 block text-white/65">{ar ? "محسوبة من المستندات والتحصيل والربحية" : "Documents, collection, and profitability"}</small></div>
        </div>
      </aside>

      <main className="min-w-0 flex-1 lg:ps-5">
        <header className="mb-5 flex flex-wrap items-center gap-3 rounded-2xl border border-daftar-line bg-daftar-card p-3 shadow-sm no-print">
          <button aria-label="open menu" className="grid h-11 w-11 place-items-center rounded-xl border border-daftar-line lg:hidden" onClick={() => setMenuOpen(true)}><Menu/></button>
          <div className="me-auto min-w-[190px]"><small className="text-daftar-muted">{ar ? "نظام تشغيل مكتب المحاسبة" : "Accounting office operating system"}</small><h1 className="m-0 text-xl font-black">{ar ? active.ar : active.en}</h1></div>
          <label className="flex min-w-[220px] flex-1 items-center gap-2 rounded-xl border border-daftar-line px-3 md:max-w-sm"><Search size={18} className="text-daftar-muted"/><input className="min-w-0 flex-1 border-0 bg-transparent p-2 shadow-none" value={query} onChange={(event) => setQuery(event.target.value)} placeholder={ar ? "ابحث في القسم الحالي..." : "Search current section..."}/></label>
          <label className="flex items-center gap-2 rounded-xl border border-daftar-line px-3"><CalendarClock size={17}/><input aria-label="period" className="border-0 bg-transparent p-2 shadow-none" type="month" value={period} onChange={(event) => setPeriod(event.target.value)}/></label>
          <button aria-label="notifications" className="relative grid h-11 w-11 place-items-center rounded-xl border border-daftar-line"><Bell size={19}/><i className="absolute end-2 top-2 h-2 w-2 rounded-full bg-red-500"/></button>
          <button aria-label="theme" className="grid h-11 w-11 place-items-center rounded-xl border border-daftar-line" onClick={() => setTheme(resolvedTheme === "dark" ? "light" : "dark")}>{resolvedTheme === "dark" ? <Sun size={19}/> : <Moon size={19}/>}</button>
          <button className="btn btn-primary" onClick={() => setClientFormOpen(true)}><Plus size={18}/>{ar ? "عميل جديد" : "New client"}</button>
        </header>

        {notice && <div className="fixed bottom-6 start-1/2 z-[90] flex max-w-[90vw] -translate-x-1/2 items-center gap-2 rounded-2xl bg-slate-950 px-5 py-3 font-bold text-white shadow-2xl"><CheckCircle2 className="shrink-0 text-emerald-400" size={19}/>{notice}</div>}
        {view === "overview" && <Overview data={data} period={period} ar={ar} go={changeView}/>}
        {view === "clients" && <Clients data={data} query={query} period={period} ar={ar} selectedId={selectedClientId} onSelect={setSelectedClientId} commit={commit} flash={flash} onAdd={() => setClientFormOpen(true)}/>}
        {view === "files" && <MonthlyFiles data={data} query={query} period={period} ar={ar} commit={commit} flash={flash}/>}
        {view === "tasks" && <Tasks data={data} query={query} ar={ar} commit={commit}/>}
        {view === "documents" && <Documents data={data} query={query} period={period} ar={ar} commit={commit} flash={flash}/>}
        {view === "deadlines" && <Deadlines data={data} period={period} ar={ar} commit={commit}/>}
        {view === "reviews" && <Reviews data={data} ar={ar} commit={commit} flash={flash}/>}
        {view === "team" && <Team data={data} ar={ar} commit={commit} flash={flash}/>}
        {view === "time" && <TimeCost data={data} period={period} ar={ar} commit={commit} flash={flash}/>}
        {view === "fees" && <Fees data={data} period={period} ar={ar} commit={commit} flash={flash}/>}
        {view === "profitability" && <Profitability data={data} period={period} ar={ar}/>}
        {view === "opportunities" && <Opportunities data={data} period={period} ar={ar} commit={commit}/>}
        {view === "reports" && <Reports data={data} period={period} ar={ar}/>}
        {view === "settings" && <OfficeSettings data={data} ar={ar} commit={commit} flash={flash}/>}
      </main>
    </div>
    {clientFormOpen && <ClientForm data={data} ar={ar} onClose={() => setClientFormOpen(false)} onSave={addClient}/>}
  </div>;
}

function Overview({ data, period, ar, go }: { data: AccountingOfficeData; period: string; ar: boolean; go: (view: View) => void }) {
  const metrics = dashboardMetrics(data, period, "2026-08-02"), currency = data.settings.currency;
  const cards: Array<[string, string, Icon, string, View]> = [
    [String(metrics.activeClients), ar ? "عميل نشط" : "Active clients", Building2, "blue", "clients"], [String(metrics.openFiles), ar ? "ملف شهري مفتوح" : "Open monthly files", FolderKanban, "violet", "files"],
    [String(metrics.readyForReview), ar ? "جاهز للمراجعة" : "Ready for review", ShieldCheck, "cyan", "reviews"], [String(metrics.overdueFiles), ar ? "ملف متأخر" : "Overdue files", AlertTriangle, "red", "files"],
    [String(metrics.overdueTasks), ar ? "مهمة متأخرة" : "Overdue tasks", AlarmClock, "red", "tasks"], [String(metrics.missingDocuments), ar ? "مستند ناقص" : "Missing documents", FileClock, "amber", "documents"],
    [`${metrics.recordedHours}`, ar ? "ساعة مسجلة" : "Recorded hours", Clock3, "blue", "time"], [money(metrics.fees, currency, ar ? "ar-EG" : "en"), ar ? "أتعاب الشهر" : "Monthly fees", CircleDollarSign, "emerald", "fees"],
    [money(metrics.collected, currency, ar ? "ar-EG" : "en"), ar ? "المحصل" : "Collected", WalletCards, "emerald", "fees"], [money(metrics.outstanding, currency, ar ? "ar-EG" : "en"), ar ? "المتبقي" : "Outstanding", FileClock, "amber", "fees"],
    [money(metrics.executionCost, currency, ar ? "ar-EG" : "en"), ar ? "تكلفة التنفيذ" : "Execution cost", BriefcaseBusiness, "violet", "profitability"], [money(metrics.estimatedProfit, currency, ar ? "ar-EG" : "en"), ar ? "صافي الربح التقديري" : "Estimated profit", TrendingUp, "emerald", "profitability"],
    [`${metrics.averageClientMargin}%`, ar ? "متوسط ربحية العميل" : "Average client margin", Gauge, "blue", "profitability"], [`${metrics.teamUtilization}%`, ar ? "استغلال طاقة الفريق" : "Team utilization", Users, metrics.teamUtilization > 90 ? "red" : "cyan", "team"],
  ];
  const alerts = buildAlerts(data, period);
  return <div className="grid gap-5">
    <section className="overflow-hidden rounded-3xl bg-gradient-to-l from-[#0d315c] via-[#124d83] to-[#0e7490] p-6 text-white shadow-xl md:p-8"><div className="flex flex-col justify-between gap-6 md:flex-row md:items-end"><div><span className="inline-flex rounded-full bg-white/10 px-3 py-1 text-xs font-bold text-white/80">{period}</span><h2 className="mt-4 text-3xl font-black">{ar ? "صاحب المكتب يرى كل ما يحتاج تدخله الآن" : "Everything requiring the owner’s attention"}</h2><p className="mt-2 max-w-3xl text-white/70">{ar ? "الأرقام محسوبة من الملفات والمهام والمستندات والوقت والأتعاب المحفوظة فعلياً، وليست أرقاماً ثابتة." : "Metrics are calculated from locally saved files, tasks, documents, time, and fees."}</p></div><button onClick={() => go("reviews")} className="flex items-center gap-3 self-start rounded-2xl bg-white px-5 py-3 font-black text-[#0d315c]"><ShieldCheck/>{ar ? "ابدأ المراجعة" : "Start review"}<ChevronLeft size={17}/></button></div></section>
    <section className="grid grid-cols-2 gap-3 md:grid-cols-3 xl:grid-cols-7">{cards.map(([value, label, CardIcon, color, target]) => <button onClick={() => go(target)} key={label} className="rounded-2xl border border-daftar-line bg-daftar-card p-4 text-start shadow-sm transition hover:-translate-y-1 hover:shadow-lg"><span className={`grid h-10 w-10 place-items-center rounded-xl ${metricColor(color)}`}><CardIcon size={20}/></span><b className="mt-4 block break-words text-xl font-black">{value}</b><small className="text-daftar-muted">{label}</small></button>)}</section>
    <section className="grid gap-5 xl:grid-cols-[1.25fr_.75fr]"><article className="rounded-3xl border border-daftar-line bg-daftar-card p-6 shadow-sm"><PanelTitle icon={Bell} title={ar ? "مركز التنبيهات حسب الخطورة" : "Priority alert center"}/><div className="mt-5 grid gap-3">{alerts.map((alert) => <button onClick={() => go(alert.view)} className="flex items-start gap-3 rounded-2xl border border-daftar-line p-4 text-start hover:bg-daftar-bg" key={alert.id}><span className={`mt-1 h-3 w-3 shrink-0 rounded-full ${alert.level === "critical" ? "bg-red-500" : alert.level === "high" ? "bg-amber-500" : "bg-blue-500"}`}/><span className="min-w-0 flex-1"><b className="block">{alert.title}</b><small className="mt-1 block text-daftar-muted">{alert.details}</small></span><ChevronLeft size={18}/></button>)}</div></article><article className="rounded-3xl border border-daftar-line bg-daftar-card p-6 shadow-sm"><PanelTitle icon={Activity} title={ar ? "سجل نشاط محلي" : "Local activity"}/><p className="mt-2 text-xs text-daftar-muted">{ar ? "سجل تشغيلي على هذا الجهاز وليس Audit Log مركزيًا." : "Device-local operational history, not a central audit log."}</p><div className="mt-4 grid gap-0">{data.activities.slice(0, 7).map((item) => <div className="flex gap-3 border-b border-daftar-line py-3 last:border-0" key={item.id}><span className="grid h-8 w-8 shrink-0 place-items-center rounded-full bg-blue-50 text-blue-700"><Activity size={15}/></span><div><b className="text-sm">{item.description}</b><small className="mt-1 block text-daftar-muted">{new Date(item.at).toLocaleString(ar ? "ar-EG" : "en")}</small></div></div>)}</div></article></section>
  </div>;
}

function buildAlerts(data: AccountingOfficeData, period: string) {
  const alerts: Array<{ id: string; title: string; details: string; level: OfficePriority; view: View }> = [];
  data.requiredDocuments.filter((item) => item.period === period && ["overdue", "requested", "partial"].includes(item.status)).slice(0, 2).forEach((item) => alerts.push({ id: item.id, title: `${clientName(data, item.clientId)} — ${item.type}`, details: item.status === "overdue" ? "المستند متأخر ويعطل الملف" : "ما زال المستند ناقصاً", level: item.status === "overdue" ? "critical" : "high", view: "documents" }));
  data.deadlines.filter((item) => ["urgent", "overdue"].includes(item.status)).slice(0, 2).forEach((item) => alerts.push({ id: item.id, title: item.type, details: `${clientName(data, item.clientId)} · ${item.dueDate}`, level: item.status === "overdue" ? "critical" : "high", view: "deadlines" }));
  data.tasks.filter((item) => !["completed", "cancelled"].includes(item.status) && item.dueDate < "2026-08-02").slice(0, 2).forEach((item) => alerts.push({ id: item.id, title: item.title, details: `${clientName(data, item.clientId)} · مهمة متأخرة`, level: "critical", view: "tasks" }));
  data.fees.filter((item) => item.status === "overdue").slice(0, 1).forEach((item) => alerts.push({ id: item.id, title: `أتعاب متأخرة — ${clientName(data, item.clientId)}`, details: `${item.amount - item.collectedAmount} ${data.settings.currency}`, level: "high", view: "fees" }));
  return alerts.slice(0, 7);
}

function Clients({ data, query, period, ar, selectedId, onSelect, commit, flash, onAdd }: { data: AccountingOfficeData; query: string; period: string; ar: boolean; selectedId: string; onSelect: (id: string) => void; commit: (data: AccountingOfficeData) => void; flash: Flash; onAdd: () => void }) {
  const clients = data.clients.filter((item) => item.status !== "archived" && `${item.code} ${item.tradeName} ${item.legalName} ${item.activity}`.toLowerCase().includes(query.toLowerCase()));
  const selected = data.clients.find((item) => item.id === selectedId) || clients[0];
  const health = selected ? clientHealth(data, selected.id, period, "2026-08-02") : undefined, profit = selected ? clientProfitability(data, selected.id, period) : undefined;
  const archive = () => { if (!selected) return; const guard = canArchiveClient(data, selected.id); if (!guard.allowed) return flash(`لا يمكن أرشفة العميل: ${guard.reasons.join("، ")}`); if (confirm("سيتم إخفاء العميل مع الاحتفاظ بسجلاته التاريخية. هل تستمر؟")) commit({ ...data, clients: data.clients.map((item) => item.id === selected.id ? { ...item, status: "archived", archivedAt: new Date().toISOString() } : item) }); };
  return <div className="grid gap-5 xl:grid-cols-[1.25fr_.75fr]"><section className="rounded-3xl border border-daftar-line bg-daftar-card p-5 shadow-sm"><PanelTitle icon={Building2} title={ar ? "سجل عملاء المكتب" : "Office client register"} action={<button className="btn btn-primary" onClick={onAdd}><Plus size={17}/>{ar ? "إضافة عميل" : "Add client"}</button>}/><div className="mt-5 overflow-x-auto"><table className="min-w-[880px]"><thead><tr><th>{ar ? "الكود والعميل" : "Code & client"}</th><th>{ar ? "النشاط" : "Activity"}</th><th>{ar ? "المسؤول" : "Owner"}</th><th>{ar ? "الباقة والأتعاب" : "Package & fee"}</th><th>{ar ? "الأولوية" : "Priority"}</th><th>{ar ? "الصحة" : "Health"}</th></tr></thead><tbody>{clients.map((client) => { const score = clientHealth(data, client.id, period, "2026-08-02"); return <tr onClick={() => onSelect(client.id)} className={`cursor-pointer ${selected?.id === client.id ? "bg-blue-50/70 dark:bg-blue-950/20" : ""}`} key={client.id}><td><b>{client.tradeName}</b><small className="mt-1 block text-daftar-muted">{client.code} · {client.legalName}</small></td><td>{client.activity}<small className="block text-daftar-muted">{client.entityType}</small></td><td>{employeeName(data, client.accountantId)}<small className="block text-daftar-muted">مراجع: {employeeName(data, client.reviewerId)}</small></td><td>{data.packages.find((item) => item.id === client.packageId)?.nameAr || "خاصة"}<small className="block font-bold text-daftar-primary">{money(client.feeAmount, data.settings.currency)}</small></td><td><PriorityBadge value={client.priority}/></td><td><HealthBadge score={score.score}/></td></tr>; })}</tbody></table></div>{!clients.length && <Empty text={ar ? "لا يوجد عميل مطابق للبحث." : "No matching clients."}/>}</section>
    {selected && health && profit && <aside className="rounded-3xl border border-daftar-line bg-daftar-card p-6 shadow-sm"><div className="flex flex-wrap items-start justify-between gap-3"><div><small className="text-daftar-muted">{selected.code}</small><h2 className="mt-1 text-2xl font-black">{selected.tradeName}</h2><p className="text-sm text-daftar-muted">{selected.contactName} · {selected.phone}</p></div><HealthBadge score={health.score}/></div><div className="mt-5 grid grid-cols-2 gap-3"><MiniMetric label="ملفات الشهر" value={data.monthlyFiles.filter((item) => item.clientId === selected.id && item.period === period).length}/><MiniMetric label="مهام مفتوحة" value={data.tasks.filter((item) => item.clientId === selected.id && !["completed", "cancelled"].includes(item.status)).length}/><MiniMetric label="الساعات الفعلية" value={profit.actualHours}/><MiniMetric label="هامش الربح" value={`${profit.margin}%`}/></div><div className="mt-5 rounded-2xl bg-daftar-bg p-4"><b>لماذا صحة العميل {health.score}/100؟</b>{health.factors.slice().sort((a, b) => a.score - b.score).slice(0, 3).map((factor) => <div className="mt-3" key={factor.key}><div className="flex justify-between text-sm"><span>{factor.label}</span><b>{factor.score}</b></div><div className="mt-1 h-2 overflow-hidden rounded-full bg-slate-200"><i className="block h-full rounded-full bg-[#1769aa]" style={{ width: `${factor.score}%` }}/></div><small className="text-daftar-muted">{factor.explanation}</small></div>)}</div><div className="mt-5 grid grid-cols-2 gap-2"><button className="btn" onClick={() => navigator.clipboard.writeText(`أستاذ/ة ${selected.contactName}، نرجو مراجعة المستندات المطلوبة لشهر ${period}.`)}><Copy size={16}/>نسخ تذكير</button><a className="btn" target="_blank" rel="noreferrer" href={`https://wa.me/${selected.phone.replace(/\D/g, "")}?text=${encodeURIComponent(`أستاذ/ة ${selected.contactName}، نرجو إرسال المستندات المطلوبة لشهر ${period}.`)}`}>WhatsApp</a><button className="btn" onClick={() => window.print()}><Printer size={16}/>تقرير العميل</button><button className="btn text-red-700" onClick={archive}>أرشفة</button></div></aside>}
  </div>;
}

function MonthlyFiles({ data, query, period, ar, commit, flash }: { data: AccountingOfficeData; query: string; period: string; ar: boolean; commit: (data: AccountingOfficeData) => void; flash: Flash }) {
  const files = data.monthlyFiles.filter((file) => file.period === period && clientName(data, file.clientId).toLowerCase().includes(query.toLowerCase()));
  const generate = (clientIds?: string[]) => { const result = generateMonthlyFiles(data, period, clientIds, true); commit(result.data); flash(result.created.length ? `تم إنشاء ${result.created.length} ملف ومنع التكرار وترحيل المهام غير المكتملة` : "لم يتم إنشاء ملفات مكررة؛ كل العملاء لديهم ملف لهذه الفترة"); };
  const generateOne = () => { const code = prompt(`اكتب كود العميل:\n${data.clients.filter((item) => item.status === "active").map((item) => `${item.code} — ${item.tradeName}`).join("\n")}`); if (!code) return; const client = data.clients.find((item) => item.code.toLowerCase() === code.trim().toLowerCase() || item.tradeName.includes(code.trim())); if (!client) return flash("لم يتم العثور على العميل"); generate([client.id]); };
  const updateStatus = (id: string, status: MonthlyFileStatus) => commit({ ...data, monthlyFiles: data.monthlyFiles.map((file) => file.id === id ? { ...file, status, startedAt: file.startedAt || new Date().toISOString().slice(0, 10), closedAt: status === "closed" ? new Date().toISOString() : file.closedAt } : file) });
  return <section><PanelTitle icon={FolderKanban} title={ar ? `ملفات العملاء — ${period}` : `Client files — ${period}`} action={<div className="flex flex-wrap gap-2"><button className="btn" onClick={generateOne}><Plus size={16}/>ملف لعميل</button><button className="btn btn-primary" onClick={() => generate()}><RefreshCcw size={16}/>إنشاء ملفات الشهر الجديد</button></div>}/><div className="mt-5 grid gap-4 md:grid-cols-2 xl:grid-cols-3">{files.map((file) => { const progress = fileCompletion(file, data.tasks); return <article className="rounded-3xl border border-daftar-line bg-daftar-card p-5 shadow-sm" key={file.id}><div className="flex items-start justify-between gap-3"><span><small className="text-daftar-primary">{file.id.slice(0, 12)} · {file.period}</small><h3 className="mt-1 text-lg font-black">{clientName(data, file.clientId)}</h3></span><StatusBadge value={labels.file[file.status]}/></div><div className="mt-5 flex items-end justify-between"><span><small className="text-daftar-muted">نسبة الإنجاز</small><b className="block text-3xl">{progress}%</b></span><span className="text-end text-sm"><b>{file.receivedDocuments}/{file.expectedDocuments}</b><small className="block text-daftar-muted">مستند مستلم</small></span></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-slate-100"><i className={`block h-full rounded-full ${progress < 45 ? "bg-red-500" : progress < 80 ? "bg-amber-500" : "bg-emerald-500"}`} style={{ width: `${progress}%` }}/></div><div className="mt-4 grid grid-cols-2 gap-2 text-sm"><Info label="المحاسب" value={employeeName(data, file.accountantId)}/><Info label="المراجع" value={employeeName(data, file.reviewerId)}/><Info label="الموعد" value={shortDate(file.dueDate, ar)}/><Info label="مهام مرحّلة" value={file.carriedTaskIds.length}/></div><select className="mt-4 w-full" value={file.status} onChange={(event) => updateStatus(file.id, event.target.value as MonthlyFileStatus)}>{Object.entries(labels.file).map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select></article>; })}</div>{!files.length && <Empty text="لا توجد ملفات لهذه الفترة. اضغط «إنشاء ملفات الشهر الجديد»."/>}</section>;
}

function Tasks({ data, query, ar, commit }: { data: AccountingOfficeData; query: string; ar: boolean; commit: (data: AccountingOfficeData) => void }) {
  const [mode, setMode] = useState<"kanban" | "table">("kanban"), [adding, setAdding] = useState(false), [title, setTitle] = useState(""), [clientId, setClientId] = useState(data.clients[0]?.id || ""), [assigneeId, setAssigneeId] = useState(data.employees[0]?.id || ""), [dueDate, setDueDate] = useState("2026-08-15"), statuses = ["new", "in-progress", "waiting-client", "ready-review", "completed"] as OfficeTaskStatus[];
  const tasks = data.tasks.filter((task) => `${task.title} ${clientName(data, task.clientId)} ${employeeName(data, task.assigneeId)}`.toLowerCase().includes(query.toLowerCase()));
  const update = (id: string, status: OfficeTaskStatus) => commit({ ...data, tasks: data.tasks.map((task) => task.id === id ? { ...task, status, completedAt: status === "completed" ? new Date().toISOString() : task.completedAt } : task) });
  const create = () => { if (!title.trim()) return; const employee = data.employees.find((item) => item.id === assigneeId), now = new Date().toISOString(); commit({ ...data, tasks: [{ id: officeId("task"), title: title.trim(), clientId, monthlyFileId: data.monthlyFiles.find((file) => file.clientId === clientId && file.period === dueDate.slice(0, 7))?.id, assigneeId, priority: "medium", status: "new", startDate: now.slice(0, 10), dueDate, expectedHours: 2, actualHours: 0, hourlyCost: employee?.hourlyCost || 0, dependencyIds: [], checklist: [], recurring: false, createdAt: now }, ...data.tasks] }); setTitle(""); setAdding(false); };
  return <section><PanelTitle icon={ClipboardCheck} title={ar ? "إدارة المهام وقائمة العمل" : "Tasks and work queue"} action={<div className="flex gap-2"><button className="btn btn-primary" onClick={() => setAdding(!adding)}><Plus size={16}/>مهمة جديدة</button><button className={`btn ${mode === "kanban" ? "tab-active" : ""}`} onClick={() => setMode("kanban")}>Kanban</button><button className={`btn ${mode === "table" ? "tab-active" : ""}`} onClick={() => setMode("table")}>{ar ? "جدول" : "Table"}</button></div>}/>{adding && <div className="mt-5 grid gap-3 rounded-2xl border border-daftar-line bg-daftar-card p-4 md:grid-cols-5"><label>عنوان المهمة<input autoFocus value={title} onChange={(event) => setTitle(event.target.value)}/></label><label>العميل<select value={clientId} onChange={(event) => setClientId(event.target.value)}>{data.clients.filter((item) => item.status !== "archived").map((item) => <option value={item.id} key={item.id}>{item.tradeName}</option>)}</select></label><label>المسؤول<select value={assigneeId} onChange={(event) => setAssigneeId(event.target.value)}>{data.employees.filter((item) => item.active).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label>الموعد<input type="date" value={dueDate} onChange={(event) => setDueDate(event.target.value)}/></label><button className="btn btn-primary self-end" onClick={create}>حفظ المهمة</button></div>}{mode === "kanban" ? <div className="mt-5 flex gap-4 overflow-x-auto pb-3">{statuses.map((status) => <div className="w-[280px] shrink-0 rounded-2xl bg-[color-mix(in_srgb,var(--primary)_4%,var(--card))] p-3" key={status}><div className="mb-3 flex justify-between"><b>{labels.task[status]}</b><span className="badge">{tasks.filter((item) => item.status === status).length}</span></div><div className="grid gap-3">{tasks.filter((item) => item.status === status).map((task) => <article className="rounded-2xl border border-daftar-line bg-daftar-card p-4 shadow-sm" key={task.id}><div className="flex justify-between gap-2"><PriorityBadge value={task.priority}/><small className={task.dueDate < "2026-08-02" && task.status !== "completed" ? "font-bold text-red-600" : "text-daftar-muted"}>{shortDate(task.dueDate, ar)}</small></div><b className="mt-3 block leading-6">{task.title}</b><small className="mt-1 block text-daftar-muted">{clientName(data, task.clientId)}</small><div className="mt-3 flex justify-between border-t border-daftar-line pt-3 text-xs"><span>{employeeName(data, task.assigneeId)}</span><span>{task.actualHours}/{task.expectedHours} س</span></div><select className="mt-3 w-full" value={task.status} onChange={(event) => update(task.id, event.target.value as OfficeTaskStatus)}>{statuses.map((item) => <option key={item} value={item}>{labels.task[item]}</option>)}</select></article>)}</div></div>)}</div> : <Table headers={["المهمة", "العميل", "المسؤول", "الموعد", "الساعات", "الحالة"]}>{tasks.map((task) => <tr key={task.id}><td><b>{task.title}</b><small className="block text-daftar-muted">{task.id}</small></td><td>{clientName(data, task.clientId)}</td><td>{employeeName(data, task.assigneeId)}</td><td>{shortDate(task.dueDate, ar)}</td><td>{task.actualHours}/{task.expectedHours}</td><td><select value={task.status} onChange={(event) => update(task.id, event.target.value as OfficeTaskStatus)}>{statuses.map((item) => <option key={item} value={item}>{labels.task[item]}</option>)}</select></td></tr>)}</Table>}</section>;
}

function Documents({ data, query, period, ar, commit, flash }: { data: AccountingOfficeData; query: string; period: string; ar: boolean; commit: (data: AccountingOfficeData) => void; flash: Flash }) {
  const docs = data.requiredDocuments.filter((item) => item.period === period && `${item.type} ${clientName(data, item.clientId)}`.toLowerCase().includes(query.toLowerCase()));
  const update = (id: string, status: RequiredDocumentStatus) => commit({ ...data, requiredDocuments: data.requiredDocuments.map((item) => item.id === id ? { ...item, status, receivedAt: status === "received" ? new Date().toISOString().slice(0, 10) : item.receivedAt } : item) });
  const remind = (id: string, openWhatsApp: boolean) => { const doc = data.requiredDocuments.find((item) => item.id === id), client = data.clients.find((item) => item.id === doc?.clientId); if (!doc || !client) return; const missing = data.requiredDocuments.filter((item) => item.clientId === client.id && item.period === period && !["received", "not-required"].includes(item.status)).map((item) => item.type).join("، "); const message = data.settings.reminderTemplate.replace("[الاسم]", client.contactName).replace("[الشهر]", period).replace("[التاريخ]", doc.period).replace("[القائمة]", missing); navigator.clipboard.writeText(message); commit({ ...data, requiredDocuments: data.requiredDocuments.map((item) => item.id === id ? { ...item, status: item.status === "not-requested" ? "requested" : item.status, requestedAt: item.requestedAt || new Date().toISOString(), reminderCount: item.reminderCount + 1 } : item), activities: [{ id: officeId("activity"), type: "reminder", description: `تم تسجيل تذكير للعميل ${client.tradeName}`, clientId: client.id, entityId: id, at: new Date().toISOString() }, ...data.activities] }); flash("تم نسخ الرسالة وتسجيل التذكير محلياً — لم يتم إرسالها تلقائياً"); if (openWhatsApp) window.open(`https://wa.me/${client.phone.replace(/\D/g, "")}?text=${encodeURIComponent(message)}`, "_blank", "noopener,noreferrer"); };
  return <section className="rounded-3xl border border-daftar-line bg-daftar-card p-5 shadow-sm"><PanelTitle icon={FileClock} title={ar ? "مركز المستندات المطلوبة" : "Required documents center"}/><Table headers={["العميل", "المستند", "الفترة", "الحالة", "المتابع", "التذكيرات", "إجراء"]}>{docs.map((doc) => <tr key={doc.id}><td>{clientName(data, doc.clientId)}</td><td><b>{doc.type}</b></td><td>{doc.period}</td><td><select value={doc.status} onChange={(event) => update(doc.id, event.target.value as RequiredDocumentStatus)}>{Object.entries(labels.document).map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select></td><td>{employeeName(data, doc.followUpEmployeeId)}</td><td>{doc.reminderCount}</td><td><div className="flex gap-2"><button className="btn" onClick={() => remind(doc.id, false)}><Copy size={15}/>نسخ</button><button className="btn" onClick={() => remind(doc.id, true)}>WhatsApp</button></div></td></tr>)}</Table></section>;
}

function Deadlines({ data, period, ar, commit }: { data: AccountingOfficeData; period: string; ar: boolean; commit: (data: AccountingOfficeData) => void }) {
  const deadlines = data.deadlines.filter((item) => item.period.slice(0, 7) <= period).sort((a, b) => a.dueDate.localeCompare(b.dueDate));
  const levels: OfficeDeadlineLevel[] = ["normal", "near", "urgent", "overdue", "completed"];
  const names = { normal: "طبيعي", near: "قريب", urgent: "عاجل", overdue: "متأخر", completed: "مكتمل" };
  const add = () => { const type = prompt("اسم الالتزام أو الموعد"); if (!type) return; const dueDate = prompt("تاريخ الاستحقاق بصيغة YYYY-MM-DD", `${period}-20`); if (!dueDate || !/^\d{4}-\d{2}-\d{2}$/.test(dueDate)) return; const client = data.clients.find((item) => item.status !== "archived"); if (!client) return; commit({ ...data, deadlines: [{ id: officeId("deadline"), clientId: client.id, type, period, dueDate, employeeId: client.accountantId, reviewerId: client.reviewerId, status: "normal", createdAt: new Date().toISOString() }, ...data.deadlines] }); };
  return <section><PanelTitle icon={CalendarClock} title={ar ? "تقويم الالتزامات والمواعيد" : "Deadlines and commitments"} action={<button className="btn btn-primary" onClick={add}><Plus size={16}/>إضافة التزام</button>}/><div className="mt-5 grid gap-4 md:grid-cols-2 xl:grid-cols-3">{deadlines.map((item) => { const days = Math.ceil((new Date(item.dueDate).getTime() - new Date("2026-08-02").getTime()) / 86_400_000); return <article className="rounded-3xl border border-daftar-line bg-daftar-card p-5 shadow-sm" key={item.id}><div className="flex justify-between"><StatusBadge value={names[item.status]}/><b className={days < 0 ? "text-red-600" : days <= 5 ? "text-amber-600" : "text-daftar-primary"}>{days < 0 ? `متأخر ${Math.abs(days)} يوم` : `${days} يوم متبقٍ`}</b></div><h3 className="mt-4 text-lg font-black">{item.type}</h3><p className="text-daftar-muted">{clientName(data, item.clientId)} · {item.period}</p><div className="mt-4 grid grid-cols-2 gap-2"><Info label="الاستحقاق" value={shortDate(item.dueDate, ar)}/><Info label="المسؤول" value={employeeName(data, item.employeeId)}/></div><select className="mt-4 w-full" value={item.status} onChange={(event) => commit({ ...data, deadlines: data.deadlines.map((deadline) => deadline.id === item.id ? { ...deadline, status: event.target.value as OfficeDeadlineLevel } : deadline) })}>{levels.map((level) => <option value={level} key={level}>{names[level]}</option>)}</select></article>; })}</div></section>;
}

function Reviews({ data, ar, commit, flash }: { data: AccountingOfficeData; ar: boolean; commit: (data: AccountingOfficeData) => void; flash: Flash }) {
  const [selectedId, setSelectedId] = useState(data.reviews[0]?.id || ""), selected = data.reviews.find((item) => item.id === selectedId) || data.reviews[0];
  const toggle = (checkId: string) => commit({ ...data, reviews: data.reviews.map((review) => review.id === selected?.id ? { ...review, checklist: review.checklist.map((item) => item.id === checkId ? { ...item, completed: !item.completed } : item) } : review) });
  const approve = () => { if (!selected?.checklist.every((item) => item.completed)) return flash("أكمل قائمة المراجعة قبل الاعتماد"); commit({ ...data, reviews: data.reviews.map((review) => review.id === selected.id ? { ...review, status: "approved", reviewedAt: new Date().toISOString(), result: "approved" } : review), monthlyFiles: data.monthlyFiles.map((file) => file.id === selected.monthlyFileId ? { ...file, status: "reviewed" } : file), activities: [{ id: officeId("activity"), type: "review", description: `تم اعتماد مراجعة ${clientName(data, selected.clientId)}`, clientId: selected.clientId, employeeId: selected.reviewerId, entityId: selected.id, at: new Date().toISOString() }, ...data.activities] }); flash("تم اعتماد المراجعة وتحديث حالة الملف"); };
  return <div className="grid gap-5 xl:grid-cols-[1fr_.7fr]"><section className="rounded-3xl border border-daftar-line bg-daftar-card p-5 shadow-sm"><PanelTitle icon={ShieldCheck} title={ar ? "قائمة انتظار المراجعة" : "Review queue"}/><div className="mt-5 grid gap-3">{data.reviews.map((review) => <button onClick={() => setSelectedId(review.id)} className={`rounded-2xl border p-4 text-start ${selected?.id === review.id ? "border-blue-400 bg-blue-50/70 dark:bg-blue-950/20" : "border-daftar-line"}`} key={review.id}><div className="flex justify-between"><b>{clientName(data, review.clientId)}</b><StatusBadge value={review.status}/></div><small className="mt-2 block text-daftar-muted">{review.type} · {employeeName(data, review.reviewerId)}</small><div className="mt-3 h-2 overflow-hidden rounded-full bg-slate-100"><i className="block h-full rounded-full bg-[#1769aa]" style={{ width: `${review.checklist.filter((item) => item.completed).length / review.checklist.length * 100}%` }}/></div></button>)}</div></section>{selected && <aside className="rounded-3xl border border-daftar-line bg-daftar-card p-6 shadow-sm"><small className="text-daftar-muted">قائمة فحص قابلة للتخصيص</small><h2 className="mt-1 text-xl font-black">{clientName(data, selected.clientId)}</h2><div className="mt-5 grid gap-2">{selected.checklist.map((item) => <button onClick={() => toggle(item.id)} className={`flex items-center gap-3 rounded-xl border p-3 text-start ${item.completed ? "border-emerald-200 bg-emerald-50 text-emerald-900" : "border-daftar-line"}`} key={item.id}><span className={`grid h-6 w-6 place-items-center rounded-md border ${item.completed ? "border-emerald-500 bg-emerald-500 text-white" : "border-slate-300"}`}>{item.completed && <Check size={15}/>}</span><b className="text-sm">{item.title}</b></button>)}</div><div className="mt-5 grid grid-cols-2 gap-2"><button className="btn" onClick={() => commit({ ...data, reviews: data.reviews.map((review) => review.id === selected.id ? { ...review, status: "changes-required", result: "returned" } : review) })}>إرجاع للتعديل</button><button className="btn btn-primary" onClick={approve}>اعتماد الملف</button></div><p className="mt-4 text-xs text-daftar-muted">يسجل النظام محلياً من راجع وتاريخ النتيجة؛ هذا ليس Audit Log مركزياً غير قابل للتلاعب.</p></aside>}</div>;
}

function Team({ data, ar, commit, flash }: { data: AccountingOfficeData; ar: boolean; commit: (data: AccountingOfficeData) => void; flash: Flash }) {
  const add = () => { const name = prompt("اسم الموظف"); if (!name?.trim()) return; if (data.employees.some((item) => item.name === name.trim() && item.active)) return flash("يوجد موظف بنفس الاسم"); const role = "accountant" as const; commit({ ...data, employees: [...data.employees, { id: officeId("employee"), name: name.trim(), role, hourlyCost: data.settings.roleHourlyCosts[role], dailyCapacityHours: data.settings.dailyHours, active: true, createdAt: new Date().toISOString() }] }); };
  return <section><PanelTitle icon={Users} title={ar ? "توزيع العمل وطاقة الفريق" : "Team capacity and workload"} action={<button className="btn btn-primary" onClick={add}><Plus size={16}/>إضافة موظف</button>}/><div className="mt-5 grid gap-4 md:grid-cols-2 xl:grid-cols-4">{data.employees.filter((item) => item.active).map((employee) => { const workload = employeeWorkload(data, employee.id, "2026-08-02"); return <article className="rounded-3xl border border-daftar-line bg-daftar-card p-5 shadow-sm" key={employee.id}><div className="flex items-center gap-3"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-blue-50 text-lg font-black text-blue-700">{employee.name.split(" ").map((part) => part[0]).join("")}</span><span><b className="block">{employee.name}</b><small className="text-daftar-muted">{employee.role} · {money(employee.hourlyCost, data.settings.currency)}/س</small></span></div><div className="mt-5 flex items-end justify-between"><span><small className="text-daftar-muted">ضغط العمل</small><b className="block text-3xl">{workload.utilization}%</b></span><WorkloadBadge level={workload.level}/></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-slate-100"><i className={`block h-full rounded-full ${workload.level === "critical" ? "bg-red-500" : workload.level === "high" ? "bg-amber-500" : "bg-emerald-500"}`} style={{ width: `${Math.min(workload.utilization, 100)}%` }}/></div><div className="mt-4 grid grid-cols-3 gap-2 text-center"><MiniMetric label="مطلوب" value={`${workload.requiredHours}س`}/><MiniMetric label="متاح" value={`${workload.availableHours}س`}/><MiniMetric label="متأخر" value={workload.overdueTasks}/></div><p className="mt-4 rounded-xl bg-daftar-bg p-3 text-sm">{workload.suggestion}</p></article>; })}</div></section>;
}

function TimeCost({ data, period, ar, commit, flash }: { data: AccountingOfficeData; period: string; ar: boolean; commit: (data: AccountingOfficeData) => void; flash: Flash }) {
  const [employeeId, setEmployeeId] = useState(data.employees[0]?.id || ""), [clientId, setClientId] = useState(data.clients[0]?.id || ""), [taskId, setTaskId] = useState(""), [description, setDescription] = useState("");
  const active = data.timeEntries.find((entry) => !entry.endedAt), entries = data.timeEntries.filter((entry) => entry.startedAt.slice(0, 7) === period);
  const begin = () => { try { commit(startTimer(data, { employeeId, clientId, taskId: taskId || undefined, monthlyFileId: data.tasks.find((task) => task.id === taskId)?.monthlyFileId, billable: true, description: description || "عمل محاسبي" })); flash("بدأ المؤقت. لا يمكن تشغيل مؤقت ثانٍ قبل إيقافه."); } catch { flash("يوجد مؤقت نشط بالفعل؛ أوقفه أولاً"); } };
  const stop = () => { if (!active) return; commit(stopTimer(data, active.id)); flash("تم إيقاف المؤقت وإضافة الوقت إلى المهمة"); };
  const manual = () => { const hours = Number(prompt("عدد الساعات؟", "1")); if (!hours || hours < 0) return; const employee = data.employees.find((item) => item.id === employeeId); const now = new Date().toISOString(); commit({ ...data, timeEntries: [{ id: officeId("time"), clientId, taskId: taskId || undefined, employeeId, startedAt: now, endedAt: now, hours, hourlyCost: employee?.hourlyCost || 0, billable: true, description: description || "وقت مضاف يدوياً", createdAt: now }, ...data.timeEntries], tasks: data.tasks.map((task) => task.id === taskId ? { ...task, actualHours: task.actualHours + hours } : task) }); };
  return <div className="grid gap-5"><section className="rounded-3xl border border-daftar-line bg-daftar-card p-6 shadow-sm"><PanelTitle icon={Clock3} title={ar ? "تسجيل الوقت وتكلفة العمل" : "Time tracking and work cost"}/><div className="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-5"><label>الموظف<select value={employeeId} onChange={(event) => setEmployeeId(event.target.value)}>{data.employees.filter((item) => item.active).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label>العميل<select value={clientId} onChange={(event) => { setClientId(event.target.value); setTaskId(""); }}>{data.clients.filter((item) => item.status !== "archived").map((item) => <option value={item.id} key={item.id}>{item.tradeName}</option>)}</select></label><label>المهمة<select value={taskId} onChange={(event) => setTaskId(event.target.value)}><option value="">بدون مهمة</option>{data.tasks.filter((item) => item.clientId === clientId && !["completed", "cancelled"].includes(item.status)).map((item) => <option value={item.id} key={item.id}>{item.title}</option>)}</select></label><label>وصف العمل<input value={description} onChange={(event) => setDescription(event.target.value)}/></label><div className="flex items-end gap-2">{active ? <button className="btn btn-primary w-full" onClick={stop}><Square size={16}/>إيقاف المؤقت</button> : <button className="btn btn-primary w-full" onClick={begin}><Play size={16}/>تشغيل المؤقت</button>}<button title="إضافة وقت يدوي" className="btn" onClick={manual}><Plus size={16}/></button></div></div>{active && <div className="mt-4 flex items-center gap-3 rounded-2xl bg-emerald-50 p-4 text-emerald-900"><span className="relative flex h-3 w-3"><i className="absolute inline-flex h-full w-full animate-ping rounded-full bg-emerald-400 opacity-75"/><i className="relative inline-flex h-3 w-3 rounded-full bg-emerald-500"/></span><b>المؤقت يعمل: {employeeName(data, active.employeeId)} — {clientName(data, active.clientId)}</b><small>{new Date(active.startedAt).toLocaleTimeString(ar ? "ar-EG" : "en")}</small></div>}</section><section className="rounded-3xl border border-daftar-line bg-daftar-card p-5 shadow-sm"><Table headers={["التاريخ", "الموظف", "العميل", "الوصف", "الساعات", "قابلة للفوترة", "التكلفة"]}>{entries.map((entry) => <tr key={entry.id}><td>{new Date(entry.startedAt).toLocaleDateString(ar ? "ar-EG" : "en")}</td><td>{employeeName(data, entry.employeeId)}</td><td>{clientName(data, entry.clientId)}</td><td>{entry.description}</td><td><b>{entry.hours}</b></td><td>{entry.billable ? "نعم" : "لا"}</td><td>{money(entry.hours * entry.hourlyCost, data.settings.currency)}</td></tr>)}</Table></section></div>;
}

function Fees({ data, period, ar, commit, flash }: { data: AccountingOfficeData; period: string; ar: boolean; commit: (data: AccountingOfficeData) => void; flash: Flash }) {
  const summary = feeSummary(data, period), fees = data.fees.filter((item) => item.period === period);
  const collect = (id: string) => { const fee = data.fees.find((item) => item.id === id); if (!fee) return; const remaining = fee.amount - fee.collectedAmount, amount = Number(prompt(`المبلغ المحصل — المتبقي ${remaining}`, String(remaining))); if (!amount || amount <= 0 || amount > remaining) return flash("أدخل مبلغاً صحيحاً لا يتجاوز المتبقي"); const collectedAmount = fee.collectedAmount + amount, now = new Date().toISOString(); commit({ ...data, fees: data.fees.map((item) => item.id === id ? { ...item, collectedAmount, status: collectedAmount >= item.amount ? "collected" : "partial", lastCollectionAt: now.slice(0, 10), collectionMethod: "تحويل/نقدي" } : item), collections: [{ id: officeId("collection"), feeId: id, clientId: fee.clientId, amount, date: now.slice(0, 10), method: "تحويل/نقدي", createdAt: now }, ...data.collections], activities: [{ id: officeId("activity"), type: "collection", description: `تحصيل ${amount} من ${clientName(data, fee.clientId)}`, clientId: fee.clientId, entityId: id, at: now }, ...data.activities] }); flash("تم تسجيل التحصيل وتحديث المتبقي"); };
  const addFee = () => { const code = prompt("كود العميل"); const client = data.clients.find((item) => item.code.toLowerCase() === code?.trim().toLowerCase()); if (!client) return flash("كود العميل غير موجود"); if (data.fees.some((item) => item.clientId === client.id && item.period === period && item.serviceId === "svc-bookkeeping" && item.status !== "cancelled")) return flash("توجد مطالبة أتعاب لنفس العميل والفترة والخدمة"); const amount = Number(prompt("قيمة الأتعاب", String(client.feeAmount))); if (!amount || amount < 0) return; const now = new Date().toISOString(); commit({ ...data, fees: [{ id: officeId("fee"), clientId: client.id, period, serviceId: "svc-bookkeeping", amount, dueDate: `${period}-${String(client.feeDueDay).padStart(2, "0")}`, status: "due", collectedAmount: 0, createdAt: now }, ...data.fees] }); };
  return <div className="grid gap-5"><section className="grid grid-cols-2 gap-3 md:grid-cols-5">{[[summary.total, "إجمالي الأتعاب"], [summary.collected, "المحصل"], [summary.outstanding, "المتبقي"], [summary.overdue, "المتأخر"], [`${summary.collectionRate}%`, "معدل التحصيل"]].map(([value, label]) => <article className="rounded-2xl border border-daftar-line bg-daftar-card p-4 shadow-sm" key={label}><small className="text-daftar-muted">{label}</small><b className="mt-2 block text-xl">{typeof value === "number" ? money(value, data.settings.currency) : value}</b></article>)}</section><section className="rounded-3xl border border-daftar-line bg-daftar-card p-5 shadow-sm"><PanelTitle icon={WalletCards} title={ar ? "مطالبات الأتعاب والتحصيلات" : "Fees and collections"} action={<button className="btn btn-primary" onClick={addFee}><Plus size={16}/>مطالبة أتعاب</button>}/><p className="mt-2 text-sm text-daftar-muted">متابعة داخلية للأتعاب وليست فاتورة ضريبية رسمية.</p><Table headers={["العميل", "الخدمة", "الاستحقاق", "المبلغ", "المحصل", "المتبقي", "الحالة", "إجراء"]}>{fees.map((fee) => <tr key={fee.id}><td>{clientName(data, fee.clientId)}</td><td>{data.services.find((item) => item.id === fee.serviceId)?.nameAr || "خدمات المكتب"}</td><td>{shortDate(fee.dueDate, ar)}</td><td>{money(fee.amount, data.settings.currency)}</td><td>{money(fee.collectedAmount, data.settings.currency)}</td><td><b>{money(fee.amount - fee.collectedAmount, data.settings.currency)}</b></td><td><StatusBadge value={labels.fee[fee.status]}/></td><td><button disabled={fee.collectedAmount >= fee.amount} className="btn" onClick={() => collect(fee.id)}>تسجيل تحصيل</button></td></tr>)}</Table></section></div>;
}

function Profitability({ data, period, ar }: { data: AccountingOfficeData; period: string; ar: boolean }) {
  const rows = data.clients.filter((item) => item.status !== "archived").map((client) => ({ client, profit: clientProfitability(data, client.id, period), health: clientHealth(data, client.id, period, "2026-08-02") })).sort((a, b) => b.profit.margin - a.profit.margin);
  return <section><PanelTitle icon={Gauge} title={ar ? "ربحية وصحة كل عميل" : "Client profitability and health"}/><div className="mt-5 grid gap-4">{rows.map(({ client, profit, health }) => <article className="rounded-3xl border border-daftar-line bg-daftar-card p-5 shadow-sm" key={client.id}><div className="grid gap-5 lg:grid-cols-[1fr_1.4fr_.8fr]"><div><small className="text-daftar-muted">{client.code}</small><h3 className="mt-1 text-xl font-black">{client.tradeName}</h3><div className="mt-3 flex gap-2"><ProfitBadge value={profit.classification}/><HealthBadge score={health.score}/></div></div><div className="grid grid-cols-2 gap-2 sm:grid-cols-4"><MiniMetric label="الإيراد" value={money(profit.revenue, data.settings.currency)}/><MiniMetric label="تكلفة الوقت" value={money(profit.laborCost, data.settings.currency)}/><MiniMetric label="إجمالي التكلفة" value={money(profit.totalCost, data.settings.currency)}/><MiniMetric label="مجمل الربح" value={money(profit.grossProfit, data.settings.currency)}/><MiniMetric label="هامش الربح" value={`${profit.margin}%`}/><MiniMetric label="إيراد/ساعة" value={money(profit.revenuePerHour, data.settings.currency)}/><MiniMetric label="المتفق" value={`${profit.agreedHours}س`}/><MiniMetric label="الفعلي" value={`${profit.actualHours}س`}/></div><div className="rounded-2xl bg-daftar-bg p-4"><b>تفسير النتيجة</b>{profit.reasons.length ? <ul className="mt-2 list-disc space-y-1 ps-5 text-sm text-daftar-muted">{profit.reasons.map((reason) => <li key={reason}>{reason}</li>)}</ul> : <p className="mt-2 text-sm text-emerald-700">الأتعاب والوقت والتكلفة في مستوى جيد.</p>}</div></div></article>)}</div></section>;
}

function Opportunities({ data, period, ar, commit }: { data: AccountingOfficeData; period: string; ar: boolean; commit: (data: AccountingOfficeData) => void }) {
  const detected = useMemo(() => detectRevenueOpportunities(data, period), [data, period]);
  const merged = detected.map((item) => data.opportunities.find((saved) => saved.clientId === item.clientId && saved.rule === item.rule) || item);
  const update = (opportunity: RevenueOpportunity, status: RevenueOpportunity["status"]) => { const exists = data.opportunities.some((item) => item.clientId === opportunity.clientId && item.rule === opportunity.rule); commit({ ...data, opportunities: exists ? data.opportunities.map((item) => item.clientId === opportunity.clientId && item.rule === opportunity.rule ? { ...item, status } : item) : [{ ...opportunity, status }, ...data.opportunities] }); };
  const totals = merged.filter((item) => !["lost", "deferred"].includes(item.status)).reduce((sum, item) => ({ revenue: sum.revenue + item.expectedMonthlyRevenue, cost: sum.cost + item.expectedCost, profit: sum.profit + item.expectedProfit }), { revenue: 0, cost: 0, profit: 0 });
  return <div className="grid gap-5"><section className="overflow-hidden rounded-3xl bg-gradient-to-l from-[#0d315c] to-[#0e9270] p-6 text-white"><small className="text-white/65">{ar ? "قواعد محلية واضحة — لا يوجد AI خارجي" : "Explainable local rules — no external AI"}</small><h2 className="mt-2 text-2xl font-black">{ar ? "فرص زيادة إيرادات المكتب" : "Revenue growth opportunities"}</h2><div className="mt-5 grid grid-cols-3 gap-3"><MiniMetric label={ar ? "إيراد شهري متوقع" : "Expected monthly revenue"} value={money(totals.revenue, data.settings.currency)}/><MiniMetric label={ar ? "إيراد سنوي متوقع" : "Expected annual revenue"} value={money(totals.revenue * 12, data.settings.currency)}/><MiniMetric label={ar ? "ربح شهري متوقع" : "Expected monthly profit"} value={money(totals.profit, data.settings.currency)}/></div></section><section className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{merged.map((item) => <article className="rounded-3xl border border-daftar-line bg-daftar-card p-5 shadow-sm" key={`${item.clientId}-${item.rule}`}><div className="flex justify-between gap-2"><PriorityBadge value={item.priority}/><StatusBadge value={labels.opportunity[item.status]}/></div><small className="mt-4 block text-daftar-primary">{clientName(data, item.clientId)}</small><h3 className="mt-1 text-lg font-black">{item.serviceName}</h3><p className="mt-2 text-sm leading-6 text-daftar-muted">{item.reason}</p><div className="mt-4 grid grid-cols-2 gap-2"><MiniMetric label={ar ? "الإيراد" : "Revenue"} value={money(item.expectedMonthlyRevenue, data.settings.currency)}/><MiniMetric label={ar ? "الربح" : "Profit"} value={money(item.expectedProfit, data.settings.currency)}/></div><details className="mt-3 rounded-xl bg-daftar-bg p-3 text-sm"><summary className="cursor-pointer font-bold">{ar ? "لماذا ظهر الاقتراح؟" : "Why was this suggested?"}</summary><p className="mt-2 text-daftar-muted">{ar ? `القاعدة: ${item.rule}. الاقتراح احتمالي ويحتاج مراجعة وتواصل مع العميل.` : `Rule: ${item.rule}. Review before contacting the client.`}</p></details><select className="mt-4 w-full" value={item.status} onChange={(event) => update(item, event.target.value as RevenueOpportunity["status"])}>{Object.entries(labels.opportunity).map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select></article>)}</section></div>;
}

function Reports({ data, period, ar }: { data: AccountingOfficeData; period: string; ar: boolean }) {
  const catalog = [["clients", "حالة العملاء"], ["files", "الملفات الشهرية"], ["overdue-tasks", "المهام المتأخرة"], ["documents", "المستندات الناقصة"], ["deadlines", "الالتزامات القادمة"], ["workload", "ضغط عمل الموظفين"], ["time", "الوقت المسجل"], ["time-variance", "المتوقع مقابل الفعلي"], ["costs", "تكلفة العملاء"], ["profitability", "ربحية العملاء"], ["fees", "الأتعاب والتحصيل"], ["extra-services", "الخدمات الإضافية"], ["opportunities", "فرص زيادة الإيرادات"], ["quality", "جودة المراجعة"], ["performance", "أداء المكتب الشهري"]] as const;
  const [report, setReport] = useState<(typeof catalog)[number][0]>("profitability"), current = officeReport(data, period, report);
  const csv = () => { const rows = [current.headers, ...current.rows], content = `\uFEFF${rows.map((row) => row.map((cell) => `"${String(cell).replaceAll('"', '""')}"`).join(",")).join("\r\n")}`; const link = document.createElement("a"); link.href = URL.createObjectURL(new Blob([content], { type: "text/csv;charset=utf-8" })); link.download = `finora-office-${report}-${period}.csv`; link.click(); URL.revokeObjectURL(link.href); };
  return <section className="rounded-3xl border border-daftar-line bg-daftar-card p-6 shadow-sm print:border-0 print:shadow-none"><PanelTitle icon={BarChart3} title={ar ? "تقارير تشغيل المكتب" : "Office operations reports"} action={<div className="flex gap-2 no-print"><button className="btn" onClick={csv}>CSV</button><button className="btn btn-primary" onClick={() => window.print()}><Printer size={17}/>طباعة / PDF</button></div>}/><div className="mt-5 grid gap-2 no-print sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5">{catalog.map(([id, name], index) => <button className={`rounded-xl border px-3 py-3 text-start text-sm font-bold ${report === id ? "border-blue-600 bg-blue-50 text-blue-800" : "border-daftar-line bg-daftar-card"}`} onClick={() => setReport(id)} key={id}><span className="me-2 text-daftar-muted">{index + 1}.</span>{name}</button>)}</div><div className="mt-6"><div className="mb-4 flex flex-wrap items-end justify-between gap-3"><div><small className="text-daftar-muted">FINORA OFFICE · {period}</small><h2>{current.title}</h2></div><b>{current.rows.length} سجل</b></div><Table headers={current.headers}>{current.rows.map((row, index) => <tr key={`${report}-${index}`}>{row.map((cell, cellIndex) => <td key={`${index}-${cellIndex}`}>{cell}</td>)}</tr>)}</Table>{!current.rows.length && <Empty text="لا توجد بيانات لهذا التقرير في الفترة المختارة."/>}</div></section>;
}

type OfficeReportId = "clients" | "files" | "overdue-tasks" | "documents" | "deadlines" | "workload" | "time" | "time-variance" | "costs" | "profitability" | "fees" | "extra-services" | "opportunities" | "quality" | "performance";
function officeReport(data: AccountingOfficeData, period: string, report: OfficeReportId): { title: string; headers: string[]; rows: Array<Array<string | number>> } {
  const profitability = data.clients.filter((item) => item.status !== "archived").map((client) => ({ client, value: clientProfitability(data, client.id, period) })), opportunities = detectRevenueOpportunities(data, period), metrics = dashboardMetrics(data, period, "2026-08-02");
  if (report === "clients") return { title: "تقرير حالة العملاء", headers: ["الكود", "العميل", "النشاط", "الحالة", "المسؤول", "درجة الصحة"], rows: data.clients.filter((item) => item.status !== "archived").map((client) => [client.code, client.tradeName, client.activity, client.status, employeeName(data, client.accountantId), clientHealth(data, client.id, period, "2026-08-02").score]) };
  if (report === "files") return { title: "تقرير الملفات الشهرية", headers: ["العميل", "الفترة", "الحالة", "الإنجاز", "المستندات", "الموعد"], rows: data.monthlyFiles.filter((item) => item.period === period).map((file) => [clientName(data, file.clientId), file.period, labels.file[file.status], `${fileCompletion(file, data.tasks)}%`, `${file.receivedDocuments}/${file.expectedDocuments}`, file.dueDate]) };
  if (report === "overdue-tasks") return { title: "تقرير المهام المتأخرة", headers: ["العميل", "المهمة", "المسؤول", "الموعد", "الساعات"], rows: data.tasks.filter((item) => item.dueDate < "2026-08-02" && !["completed", "cancelled"].includes(item.status)).map((task) => [clientName(data, task.clientId), task.title, employeeName(data, task.assigneeId), task.dueDate, `${task.actualHours}/${task.expectedHours}`]) };
  if (report === "documents") return { title: "تقرير المستندات الناقصة", headers: ["العميل", "المستند", "الفترة", "الحالة", "التذكيرات"], rows: data.requiredDocuments.filter((item) => !["received", "not-required"].includes(item.status)).map((item) => [clientName(data, item.clientId), item.type, item.period, labels.document[item.status], item.reminderCount]) };
  if (report === "deadlines") return { title: "تقرير الالتزامات القادمة", headers: ["العميل", "الالتزام", "الفترة", "الاستحقاق", "الحالة", "المسؤول"], rows: data.deadlines.filter((item) => item.status !== "completed").map((item) => [clientName(data, item.clientId), item.type, item.period, item.dueDate, item.status, employeeName(data, item.employeeId)]) };
  if (report === "workload") return { title: "تقرير ضغط عمل الموظفين", headers: ["الموظف", "مطلوب", "متاح", "الاستغلال", "العاجل", "المتأخر", "الحالة"], rows: data.employees.map((employee) => { const value = employeeWorkload(data, employee.id, "2026-08-02"); return [employee.name, value.requiredHours, value.availableHours, `${value.utilization}%`, value.urgentTasks, value.overdueTasks, value.level]; }) };
  if (report === "time") return { title: "تقرير الوقت المسجل", headers: ["التاريخ", "الموظف", "العميل", "الوصف", "الساعات", "التكلفة"], rows: data.timeEntries.filter((item) => item.startedAt.slice(0, 7) === period).map((item) => [item.startedAt.slice(0, 10), employeeName(data, item.employeeId), clientName(data, item.clientId), item.description, item.hours, item.hours * item.hourlyCost]) };
  if (report === "time-variance") return { title: "تقرير الوقت المتوقع مقابل الفعلي", headers: ["العميل", "المهمة", "المتوقع", "الفعلي", "الفرق"], rows: data.tasks.filter((item) => item.startDate.slice(0, 7) <= period && item.dueDate.slice(0, 7) >= period).map((item) => [clientName(data, item.clientId), item.title, item.expectedHours, item.actualHours, item.actualHours - item.expectedHours]) };
  if (report === "costs") return { title: "تقرير تكلفة العملاء", headers: ["العميل", "تكلفة الساعات", "تكلفة إضافية", "إجمالي التكلفة"], rows: profitability.map(({ client, value }) => [client.tradeName, value.laborCost, value.additionalCost, value.totalCost]) };
  if (report === "profitability") return { title: "تقرير ربحية العملاء", headers: ["العميل", "الإيراد", "التكلفة", "الربح", "الهامش", "التصنيف"], rows: profitability.map(({ client, value }) => [client.tradeName, value.revenue, value.totalCost, value.grossProfit, `${value.margin}%`, value.classification]) };
  if (report === "fees") return { title: "تقرير الأتعاب والتحصيل", headers: ["العميل", "المبلغ", "المحصل", "المتبقي", "الاستحقاق", "الحالة"], rows: data.fees.filter((item) => item.period === period).map((fee) => [clientName(data, fee.clientId), fee.amount, fee.collectedAmount, fee.amount - fee.collectedAmount, fee.dueDate, labels.fee[fee.status]]) };
  if (report === "extra-services") return { title: "تقرير الخدمات الإضافية", headers: ["العميل", "الخدمة", "السبب", "القيمة", "الحالة"], rows: data.opportunities.filter((item) => ["offered", "negotiating", "won"].includes(item.status)).map((item) => [clientName(data, item.clientId), item.serviceName, item.reason, item.expectedMonthlyRevenue, labels.opportunity[item.status]]) };
  if (report === "opportunities") return { title: "تقرير فرص زيادة الإيرادات", headers: ["العميل", "الخدمة", "القاعدة", "الإيراد المتوقع", "الربح المتوقع", "الأولوية"], rows: opportunities.map((item) => [clientName(data, item.clientId), item.serviceName, item.rule, item.expectedMonthlyRevenue, item.expectedProfit, item.priority]) };
  if (report === "quality") return { title: "تقرير جودة المراجعة", headers: ["العميل", "المراجع", "الحالة", "المنجز", "الإجمالي", "التاريخ"], rows: data.reviews.map((item) => [clientName(data, item.clientId), employeeName(data, item.reviewerId), item.status, item.checklist.filter((check) => check.completed).length, item.checklist.length, item.reviewedAt?.slice(0, 10) || "—"]) };
  return { title: "تقرير أداء المكتب الشهري", headers: ["العملاء", "الملفات المفتوحة", "المهام المتأخرة", "المستندات الناقصة", "الساعات", "الأتعاب", "المحصل", "التكلفة", "الربح", "استغلال الفريق"], rows: [[metrics.activeClients, metrics.openFiles, metrics.overdueTasks, metrics.missingDocuments, metrics.recordedHours, metrics.fees, metrics.collected, metrics.executionCost, metrics.estimatedProfit, `${metrics.teamUtilization}%`]] };
}

function OfficeSettings({ data, ar, commit, flash }: { data: AccountingOfficeData; ar: boolean; commit: (data: AccountingOfficeData) => void; flash: Flash }) {
  const [draft, setDraft] = useState(data);
  useEffect(() => setDraft(data), [data]);
  const save = () => { commit(draft); flash(ar ? "تم حفظ إعدادات المكتب محلياً" : "Office settings saved locally"); };
  const logo = (file?: File) => { if (!file) return; if (file.size > 1_500_000) return flash("حجم الشعار كبير؛ استخدم صورة أقل من 1.5MB"); const reader = new FileReader(); reader.onload = () => setDraft({ ...draft, office: { ...draft.office, logoDataUrl: String(reader.result) } }); reader.readAsDataURL(file); };
  const reset = () => { if (!confirm("سيتم استبدال بيانات المكتب الحالية ببيانات العرض. هل تستمر؟")) return; const seeded = resetOfficeDemo(activeCompanyId()); setDraft(seeded); flash("تم تحميل بيانات تجريبية واقعية"); };
  return <div className="grid gap-5"><section className="rounded-3xl border border-daftar-line bg-daftar-card p-6 shadow-sm"><PanelTitle icon={Settings2} title={ar ? "هوية وإعدادات المكتب" : "Office identity and settings"}/><div className="mt-5 grid gap-4 md:grid-cols-2 xl:grid-cols-4"><label>اسم المكتب بالعربية<input value={draft.office.nameAr} onChange={(event) => setDraft({ ...draft, office: { ...draft.office, nameAr: event.target.value } })}/></label><label>اسم المكتب بالإنجليزية<input value={draft.office.nameEn} onChange={(event) => setDraft({ ...draft, office: { ...draft.office, nameEn: event.target.value } })}/></label><label>العملة<select value={draft.settings.currency} onChange={(event) => setDraft({ ...draft, settings: { ...draft.settings, currency: event.target.value } })}>{["EGP", "USD", "SAR", "AED"].map((item) => <option key={item}>{item}</option>)}</select></label><label>ساعات العمل اليومية<input type="number" min="1" max="16" value={draft.settings.dailyHours} onChange={(event) => setDraft({ ...draft, settings: { ...draft.settings, dailyHours: Number(event.target.value) } })}/></label><label>تنبيه قبل الموعد — أيام<input type="number" min="0" value={draft.settings.alertDaysBefore} onChange={(event) => setDraft({ ...draft, settings: { ...draft.settings, alertDaysBefore: Number(event.target.value) } })}/></label><label>بادئة العملاء<input value={draft.settings.clientPrefix} onChange={(event) => setDraft({ ...draft, settings: { ...draft.settings, clientPrefix: event.target.value.toUpperCase() } })}/></label><label>بادئة الملفات<input value={draft.settings.filePrefix} onChange={(event) => setDraft({ ...draft, settings: { ...draft.settings, filePrefix: event.target.value.toUpperCase() } })}/></label><label className="btn cursor-pointer self-end"><Upload size={16}/>رفع شعار المكتب<input className="hidden" type="file" accept="image/*" onChange={(event) => logo(event.target.files?.[0])}/></label></div><h3 className="mt-7 font-black">حدود تصنيف الربحية</h3><div className="mt-3 grid gap-3 md:grid-cols-4">{(["veryProfitable", "profitable", "review", "low"] as const).map((key) => <label key={key}>{key}<input type="number" value={draft.settings.profitabilityThresholds[key]} onChange={(event) => setDraft({ ...draft, settings: { ...draft.settings, profitabilityThresholds: { ...draft.settings.profitabilityThresholds, [key]: Number(event.target.value) } } })}/></label>)}</div><h3 className="mt-7 font-black">قالب رسالة طلب المستندات</h3><textarea className="mt-3 w-full" rows={3} value={draft.settings.reminderTemplate} onChange={(event) => setDraft({ ...draft, settings: { ...draft.settings, reminderTemplate: event.target.value } })}/><div className="mt-5 flex flex-wrap gap-2"><button className="btn btn-primary" onClick={save}>حفظ الإعدادات</button><button className="btn" onClick={reset}><RotateCcw size={16}/>تحميل بيانات تجريبية</button></div></section><section className="rounded-3xl border border-daftar-line bg-daftar-card p-6 shadow-sm"><h2>قوالب سير العمل والخدمات</h2><div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">{data.templates.map((template) => <article className="rounded-2xl border border-daftar-line p-4" key={template.id}><PackageCheck className="text-daftar-primary"/><b className="mt-3 block">{template.nameAr}</b><small className="text-daftar-muted">{template.tasks.length} مهام · {template.documents.length} مستندات · {template.expectedHours} ساعة</small><strong className="mt-3 block">{money(template.suggestedPrice, data.settings.currency)}</strong></article>)}</div></section></div>;
}

function ClientForm({ data, ar, onClose, onSave }: { data: AccountingOfficeData; ar: boolean; onClose: () => void; onSave: (client: OfficeClient) => void }) {
  const [name, setName] = useState(""), [legalName, setLegalName] = useState(""), [activity, setActivity] = useState("تجارة وتوزيع"), [contact, setContact] = useState(""), [phone, setPhone] = useState(""), [fee, setFee] = useState(6000), [accountantId, setAccountantId] = useState(data.employees.find((item) => item.role === "accountant")?.id || data.employees[0].id), [reviewerId, setReviewerId] = useState(data.employees.find((item) => item.role === "reviewer")?.id || data.employees[0].id), [templateId, setTemplateId] = useState(data.templates[0]?.id || ""), [error, setError] = useState("");
  const submit = () => { if (!name.trim() || !contact.trim() || phone.replace(/\D/g, "").length < 8) return setError("أدخل اسم العميل ومسؤول التواصل ورقم هاتف صحيح"); if (data.clients.some((item) => item.tradeName.trim() === name.trim() && item.status !== "archived")) return setError("يوجد عميل بنفس الاسم بالفعل"); const now = new Date().toISOString(), sequence = String(data.clients.length + 101).padStart(3, "0"); onSave({ id: officeId("client"), code: `${data.settings.clientPrefix}-${sequence}`, tradeName: name.trim(), legalName: legalName.trim() || name.trim(), activity, entityType: "شركة ذات مسؤولية محدودة", contactName: contact.trim(), phone: phone.trim(), contractStart: now.slice(0, 10), status: "active", accountantId, reviewerId, serviceFrequency: "monthly", packageId: data.packages[0]?.id, workflowTemplateId: templateId, feeAmount: fee, feeDueDay: 10, expectedHours: data.templates.find((item) => item.id === templateId)?.expectedHours || 16, includedServiceIds: data.packages[0]?.serviceIds || [], excludedServiceIds: [], priority: "medium", risk: "medium", responseSpeed: 75, documentCommitment: 75, reworkRate: 5, extraMonthlyCosts: 0, branches: 1, employeeCount: 0, bankTransactionVolume: 0, createdAt: now }); };
  return <div className="fixed inset-0 z-[100] overflow-y-auto bg-slate-950/55 p-4"><div role="dialog" aria-modal="true" className="mx-auto mt-8 max-w-4xl rounded-3xl bg-daftar-card p-6 shadow-2xl"><div className="flex justify-between"><div><small className="text-daftar-primary">FINORA OFFICE</small><h2 className="mt-1 text-2xl font-black">{ar ? "إضافة عميل جديد" : "Add a new client"}</h2></div><button className="btn" onClick={onClose}><X size={18}/></button></div><div className="mt-6 grid gap-4 md:grid-cols-2 xl:grid-cols-3"><label>الاسم التجاري<input autoFocus value={name} onChange={(event) => setName(event.target.value)}/></label><label>الاسم القانوني<input value={legalName} onChange={(event) => setLegalName(event.target.value)}/></label><label>النشاط<input value={activity} onChange={(event) => setActivity(event.target.value)}/></label><label>مسؤول التواصل<input value={contact} onChange={(event) => setContact(event.target.value)}/></label><label>الهاتف<input value={phone} onChange={(event) => setPhone(event.target.value)}/></label><label>الأتعاب الشهرية<input type="number" min="0" value={fee} onChange={(event) => setFee(Number(event.target.value))}/></label><label>المحاسب<select value={accountantId} onChange={(event) => setAccountantId(event.target.value)}>{data.employees.filter((item) => item.active).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label>المراجع<select value={reviewerId} onChange={(event) => setReviewerId(event.target.value)}>{data.employees.filter((item) => item.active).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label>قالب سير العمل<select value={templateId} onChange={(event) => setTemplateId(event.target.value)}>{data.templates.filter((item) => item.active).map((item) => <option value={item.id} key={item.id}>{item.nameAr}</option>)}</select></label></div>{error && <p className="mt-4 rounded-xl bg-red-50 p-3 text-red-800">{error}</p>}<div className="mt-6 flex justify-end gap-2"><button className="btn" onClick={onClose}>إلغاء</button><button className="btn btn-primary" onClick={submit}>حفظ العميل</button></div></div></div>;
}

function PanelTitle({ title, icon: IconComponent, action }: { title: string; icon: Icon; action?: React.ReactNode }) { return <div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-xl bg-blue-50 text-[#1769aa]"><IconComponent size={21}/></span><h2 className="m-0 text-xl font-black">{title}</h2></div>{action}</div>; }
function Table({ headers, children }: { headers: string[]; children: React.ReactNode }) { return <div className="mt-5 overflow-x-auto rounded-2xl border border-daftar-line"><table className="min-w-[850px] w-full"><thead><tr>{headers.map((header) => <th key={header}>{header}</th>)}</tr></thead><tbody>{children}</tbody></table></div>; }
function StatusBadge({ value }: { value: string }) { const negative = /متأخر|حرج|تعديل|overdue|changes/.test(value), positive = /مكتمل|مغلق|استلام|مراجعة|approved|collected/.test(value); return <span className={`inline-flex rounded-full px-3 py-1 text-xs font-black ${negative ? "bg-red-100 text-red-800" : positive ? "bg-emerald-100 text-emerald-800" : "bg-amber-100 text-amber-800"}`}>{value}</span>; }
function PriorityBadge({ value }: { value: OfficePriority }) { const names = { low: "منخفضة", medium: "متوسطة", high: "عالية", critical: "حرجة" }, colors = { low: "bg-slate-100 text-slate-700", medium: "bg-blue-100 text-blue-800", high: "bg-amber-100 text-amber-800", critical: "bg-red-100 text-red-800" }; return <span className={`rounded-full px-3 py-1 text-xs font-black ${colors[value]}`}>{names[value]}</span>; }
function HealthBadge({ score }: { score: number }) { return <span className={`rounded-full px-3 py-1 text-xs font-black ${score >= 85 ? "bg-emerald-100 text-emerald-800" : score >= 70 ? "bg-blue-100 text-blue-800" : score >= 50 ? "bg-amber-100 text-amber-800" : "bg-red-100 text-red-800"}`}>{score}/100 · {score >= 85 ? "ممتاز" : score >= 70 ? "جيد" : score >= 50 ? "يحتاج متابعة" : "معرض للخطر"}</span>; }
function WorkloadBadge({ level }: { level: WorkloadLevel }) { const names = { available: "متاح", balanced: "متوازن", high: "مرتفع", critical: "حرج" }, colors = { available: "bg-emerald-100 text-emerald-800", balanced: "bg-blue-100 text-blue-800", high: "bg-amber-100 text-amber-800", critical: "bg-red-100 text-red-800" }; return <span className={`rounded-full px-3 py-1 text-xs font-black ${colors[level]}`}>{names[level]}</span>; }
function ProfitBadge({ value }: { value: ClientProfitability["classification"] }) { const names = { "very-profitable": "مربح جداً", profitable: "مربح", review: "يحتاج مراجعة", low: "ضعيف الربحية", loss: "خاسر" }, colors = { "very-profitable": "bg-emerald-100 text-emerald-800", profitable: "bg-blue-100 text-blue-800", review: "bg-amber-100 text-amber-800", low: "bg-orange-100 text-orange-800", loss: "bg-red-100 text-red-800" }; return <span className={`rounded-full px-3 py-1 text-xs font-black ${colors[value]}`}>{names[value]}</span>; }
function MiniMetric({ label, value }: { label: string; value: string | number }) { return <span className="rounded-xl bg-daftar-bg p-3"><small className="block text-daftar-muted">{label}</small><b className="mt-1 block break-words">{value}</b></span>; }
function Info({ label, value }: { label: string; value: string | number }) { return <span><small className="block text-daftar-muted">{label}</small><b className="text-sm">{value}</b></span>; }
function Empty({ text }: { text: string }) { return <div className="mt-5 rounded-2xl border border-dashed border-daftar-line p-10 text-center text-daftar-muted"><FileText className="mx-auto mb-3"/>{text}</div>; }
function metricColor(value: string) { return ({ blue: "bg-blue-50 text-blue-700", violet: "bg-violet-50 text-violet-700", cyan: "bg-cyan-50 text-cyan-700", red: "bg-red-50 text-red-700", amber: "bg-amber-50 text-amber-700", emerald: "bg-emerald-50 text-emerald-700" } as Record<string, string>)[value] || "bg-slate-50 text-slate-700"; }
